        LawSkippedGap(0, 0, 3, 1);
    }
    [Xunit.Fact]
    public static void TestCompetingCutEdgesDoNotFlagEveryPair() {
        LawSkippedGap(0, 1, 1, 2);
    }
    [Xunit.Fact]
    public static void TestPixelCorrelationNeedsContrastAndPositiveCovariance() {
        emon.Port.Cells pixels = emon.Port.NewCells();
        emon.Port.CellsPush(pixels, 0);
        emon.Port.CellsPush(pixels, 128);
        emon.Port.CellsPush(pixels, 255);
        emon.Port.CellsPush(pixels, 60);
        emon.Port.CellsPush(pixels, 124);
        emon.Port.CellsPush(pixels, 188);
        emon.Port.CellsPush(pixels, 255);
        emon.Port.CellsPush(pixels, 128);
        emon.Port.CellsPush(pixels, 0);
        emon.Port.CellsPush(pixels, 180);
        emon.Port.CellsPush(pixels, 180);
        emon.Port.CellsPush(pixels, 180);
        emon.Testport.AssertEq(Seams.MsNcc(pixels, 0, 3, 3), 1, "same signal with different exposure");
        emon.Testport.AssertEq(Seams.MsNcc(pixels, 0, 6, 3), 0, "opposite signal");
        emon.Testport.AssertEq(Seams.MsNcc(pixels, 0, 9, 3), 0, "flat area cannot corroborate");
    }
}
